<?php
declare(strict_types=1);
// Restore exclusively into a NEW database. Never overwrites a live installation.
if(PHP_SAPI!=='cli')exit('CLI only');require_once dirname(__DIR__).'/bootstrap.php';
if(count($argv)!==4)exit("Usage: php restore.php archive.rpf new_readyfinance_database new_private_directory\nSet RPF_BACKUP_PASSWORD and optional RPF_DB_ADMIN / RPF_DB_ADMIN_PASSWORD privately.\n");
$file=$argv[1];$db=$argv[2];$destination=$argv[3];if(!preg_match('/^readyfinance[a-z0-9_]+$/D',$db))throw new RuntimeException('Use a new readyfinance database name.');if(file_exists($destination))throw new RuntimeException('Destination must not exist.');$password=getenv('RPF_BACKUP_PASSWORD');if(!$password)throw new RuntimeException('Backup password is required in the environment.');
$bytes=file_get_contents($file);if(substr($bytes,0,4)!=='RPF2')throw new RuntimeException('Unsupported backup format.');$salt=substr($bytes,4,16);$nonce=substr($bytes,20,12);$tag=substr($bytes,32,16);$key=hash_pbkdf2('sha256',$password,$salt,600000,32,true);$plain=openssl_decrypt(substr($bytes,48),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag,'RPF2');if($plain===false)throw new RuntimeException('Incorrect password or damaged backup.');$data=json_decode($plain,true,128,JSON_THROW_ON_ERROR);if(($data['format']??'')!=='readyfinance-backup'||($data['version']??0)!==1)throw new RuntimeException('Unsupported backup.');
$admin=new PDO('mysql:host=127.0.0.1;port=3306;charset=utf8mb4',getenv('RPF_DB_ADMIN')?:'root',getenv('RPF_DB_ADMIN_PASSWORD')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);if($admin->query('SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='.$admin->quote($db))->fetchColumn())throw new RuntimeException('Database exists; nothing changed.');
$sql='';foreach(glob(dirname(__DIR__).'/database/*.sql') as $migration)$sql.=file_get_contents($migration)."\n";preg_match_all('/CREATE TABLE(?: IF NOT EXISTS)? (\w+)/',$sql,$matches);$allowed=$matches[1];foreach(array_keys($data['tables']) as $table)if(!in_array($table,$allowed,true))throw new RuntimeException('Unexpected table in backup.');foreach($allowed as $table)if($table!=='login_attempts'&&!array_key_exists($table,$data['tables']))throw new RuntimeException('Incomplete table set.');
foreach($data['files'] as $key=>$value){if(!preg_match('/^[a-f0-9]{64}$/D',$key)||base64_decode($value,true)===false)throw new RuntimeException('Invalid document blob.');}
$admin->exec('CREATE DATABASE `'.$db.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$admin->exec('USE `'.$db.'`');$admin->exec($sql);foreach(glob(dirname(__DIR__).'/database/*.php') as $migrationFile){$migration=require $migrationFile;$migration($admin);}$admin->exec('DELETE FROM schema_migrations');$admin->beginTransaction();try{foreach($allowed as $table){if($table==='login_attempts')continue;foreach($data['tables'][$table] as $row){$keys=array_keys($row);foreach($keys as $column)if(!preg_match('/^\w+$/D',$column))throw new RuntimeException('Invalid column.');$q=$admin->prepare('INSERT INTO `'.$table.'` (`'.implode('`,`',$keys).'`) VALUES('.implode(',',array_fill(0,count($keys),'?')).')');$q->execute(array_values($row));}}$bad=$admin->query('SELECT COUNT(*) FROM (SELECT journal_id FROM journal_lines GROUP BY journal_id HAVING SUM(debit)<>SUM(credit)) x')->fetchColumn();if($bad)throw new RuntimeException('Unbalanced journals in backup.');$admin->commit();}catch(Throwable $e){if($admin->inTransaction())$admin->rollBack();throw $e;}
mkdir($destination,0700,true);mkdir($destination.'/documents',0700);foreach($data['files'] as $key=>$v)file_put_contents($destination.'/documents/'.$key,base64_decode($v,true));foreach($admin->query('SELECT storage_key,checksum FROM documents') as $d){$path=$destination.'/documents/'.$d['storage_key'];if(!is_file($path)||hash_file('sha256',$path)!==$d['checksum'])throw new RuntimeException('Document checksum mismatch.');}
file_put_contents($destination.'/restore-manifest.json',json_encode(['restored_at'=>gmdate('c'),'database'=>$db,'source_installation'=>$data['installation_uuid'],'new_installation_uuid'=>ReadyFinance\Core::uuid()]));echo "Backup verified and restored into new database $db. The live installation is unchanged. Configure a new dedicated database user before switching.\n";
